#[derive(Clone)]
struct NetworkLoginSession {
    generation: u64,
    window_id: WindowId,
    tab_id: TabId,
    failed_request_id: RequestId,
    target: PathBuf,
    cancel: Arc<std::sync::atomic::AtomicBool>,
}

#[derive(Default)]
struct NetworkLoginCoordinator {
    next_generation: u64,
    current: Option<NetworkLoginSession>,
}

impl NetworkLoginCoordinator {
    fn begin(
        &mut self,
        window_id: WindowId,
        tab_id: TabId,
        failed_request_id: RequestId,
        target: PathBuf,
    ) -> NetworkLoginSession {
        self.cancel();
        self.next_generation = self.next_generation.wrapping_add(1).max(1);
        let session = NetworkLoginSession {
            generation: self.next_generation,
            window_id,
            tab_id,
            failed_request_id,
            target,
            cancel: Arc::new(std::sync::atomic::AtomicBool::new(false)),
        };
        self.current = Some(session.clone());
        session
    }

    fn cancel(&mut self) {
        if let Some(current) = self.current.take() {
            current
                .cancel
                .store(true, std::sync::atomic::Ordering::Release);
        }
    }

    fn is_current(&self, generation: u64) -> bool {
        self.current
            .as_ref()
            .is_some_and(|current| current.generation == generation)
    }

    fn finish(&mut self, generation: u64) {
        if self.is_current(generation) {
            self.current = None;
        }
    }

    fn cancel_generation(&mut self, generation: u64) {
        if self.is_current(generation) {
            self.cancel();
        }
    }
}

