    fn right_drop_intent(
        paths: Vec<PathBuf>,
        target: PathBuf,
        allowed_effects: u32,
    ) -> platform::windows::drag_drop::DropIntent {
        platform::windows::drag_drop::DropIntent {
            paths,
            target: platform::windows::drag_drop::DropTarget::Directory(target),
            effect: platform::windows::drag_drop::DropEffect::Move,
            right_button: true,
            screen_x: 25,
            screen_y: 40,
            allowed_effects,
        }
    }

